python3 -c "
import json, yaml, sys

with open('/home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-3-projects-solver-trace-ablation--claude-sessions-agent-9514a32e/2324a771-797d-447a-8c93-e1e937d0ed1a/tool-results/mcp-agent-ml-research-read_registry-1778800661206.txt') as f:
    data = json.load(f)

registry = yaml.safe_load(data['result'])
experiments = registry if isinstance(registry, list) else registry.get('experiments', [])

from collections import Counter
from datetime import datetime, timezone, timedelta

status_counts = Counter()
running_preparing = []
done_recent = []
cron_running = []

cutoff = datetime.now(timezone.utc) - timedelta(hours=24)

for exp in experiments:
    status = exp.get('status', 'UNKNOWN')
    status_counts[status] += 1

    if status in ('RUNNING', 'PREPARING', 'ALLOCATED', 'QUEUED', 'PENDING'):
        running_preparing.append({
            'exp_id': exp.get('exp_id'),
            'status': status,
            'server': exp.get('server') or exp.get('spec', {}).get('server'),
            'gpu': exp.get('gpu') or exp.get('spec', {}).get('gpu'),
            'pid': exp.get('pid') or exp.get('spec', {}).get('pid'),
            'tmux': exp.get('tmux_session') or exp.get('spec', {}).get('tmux_session'),
            'hypothesis': exp.get('hypothesis', '')[:100],
        })

    # Done in last 24h
    if status == 'DONE':
        completed = exp.get('completed_at') or exp.get('updated_at')
        if completed:
            try:
                if isinstance(completed, str):
                    dt = datetime.fromisoformat(completed.replace('Z', '+00:00'))
                else:
                    dt = completed
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                if dt >= cutoff:
                    done_recent.append({
                        'exp_id': exp.get('exp_id'),
                        'conclusion': exp.get('conclusion'),
                        'metrics': exp.get('metrics', {}),
                        'completed_at': completed,
                    })
            except Exception as e:
                pass

    # Cron + RUNNING
    if exp.get('cron_id') and status == 'RUNNING':
        cron_running.append({
            'exp_id': exp.get('exp_id'),
            'cron_id': exp.get('cron_id'),
            'status': status,
        })

print('=== STATUS COUNTS ===')
for s, c in sorted(status_counts.items()):
    print(f'  {s}: {c}')

print()
print('=== RUNNING/PREPARING/ACTIVE ===')
if not running_preparing:
    print('  (none)')
for e in running_preparing:
    print(f'  {e[\"exp_id\"]} | {e[\"status\"]} | server={e[\"server\"]} | gpu={e[\"gpu\"]} | pid={e[\"pid\"]} | tmux={e[\"tmux\"]}')
    print(f'    hypothesis: {e[\"hypothesis\"]}')

print()
print('=== DONE (last 24h) ===')
if not done_recent:
    print('  (none)')
for e in done_recent:
    print(f'  {e[\"exp_id\"]} | conclusion={e[\"conclusion\"]} | completed={e[\"completed_at\"]}')
    print(f'    metrics: {e[\"metrics\"]}')

print()
print('=== CRON + RUNNING ===')
if not cron_running:
    print('  (none)')
for e in cron_running:
    print(f'  {e[\"exp_id\"]} | cron_id={e[\"cron_id\"]}')
"
